lib='''
from collections import Counter

def bg_color(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def bbox(grid, skip=None):
    """Bounding box (r0,r1,c0,c1) of all cells whose color is not skip (default: background)."""
    if skip is None: skip = bg_color(grid)
    pts=[(i,j) for i,r in enumerate(grid) for j,v in enumerate(r) if v!=skip]
    if not pts: return None
    return (min(i for i,_ in pts), max(i for i,_ in pts), min(j for _,j in pts), max(j for _,j in pts))

def fill_frame(grid, rects):
    """Background cells on the border of each (r0,r1,c0,c1) rectangle become 2."""
    h,w=len(grid),len(grid[0]); b=bg_color(grid); out=[r[:] for r in grid]
    for r0,r1,c0,c1 in rects:
        for i in range(r0,r1+1):
            for j in (c0,c1):
                if 0<=i<h and 0<=j<w and out[i][j]==b: out[i][j]=2
        for j in range(c0,c1+1):
            for i in (r0,r1):
                if 0<=i<h and 0<=j<w and out[i][j]==b: out[i][j]=2
    return out

def wall_count(grid, line, axis, skip=None):
    """Number of non-background cells along row (axis=0) or column (axis=1) `line`."""
    if skip is None: skip = bg_color(grid)
    if axis==0: return sum(1 for v in grid[line] if v!=skip)
    return sum(1 for r in grid if r[line]!=skip)
'''
